import itertools
from scipy.optimize import least_squares
y=dv_dt
def lib_for(u,name):
    d={}
    for p in [-2,-1,-0.5,0.5,1,2,3]:
        for k in [0,0.5,1,2]:
            if k==0: d[f"{name}^{p}"]=u**p
            else: d[f"{name}^{p}*exp(-{k}{name})"]=u**p*np.exp(-k*u)
    for k in [0.5,1,2]:
        d[f"1/(1+{k}{name}^2)"]=1/(1+k*u**2)
        d[f"{name}/(1+{k}{name}^2)"]=u/(1+k*u**2)
        d[f"{name}^2/(1+{k}{name}^2)"]=u**2/(1+k*u**2)
    d['1']=np.ones(300)
    return d
Lt=lib_for(t,'t'); Lx=lib_for(x,'x'); Lv=lib_for(v,'v')
cands={}
cands.update(Lt); cands.update(Lx); cands.update(Lv)
for n1,f1 in Lt.items():
    for n2,f2 in Lx.items(): cands[n1+'*'+n2]=f1*f2
    for n2,f2 in Lv.items(): cands[n1+'*'+n2]=f1*f2
